// Real third-party PPE detection runs locally in the browser through ONNX Runtime Web.
let ppeSessionPromise;
function mountDetector() {
  const stage=demo.querySelector('.demo-stage');
  stage.outerHTML=`<div class="detector-panel"><div class="detector-heading"><div><h4>Try PPE detection</h4><p>Choose an image and run an open-source detection model on your device.</p></div></div><label class="detector-upload" for="ppe-file">Choose an image <span>JPG, PNG or WebP · up to 10 MB</span></label><input id="ppe-file" type="file" accept="image/jpeg,image/png,image/webp"><button type="button" class="sample-photo">Run construction photo sample</button><p class="sample-credit">Photo by Paul Keheler. <a href="https://commons.wikimedia.org/wiki/File:Construction_Workers.jpg">Source</a> · <a href="https://creativecommons.org/licenses/by/2.0/">CC BY 2.0</a></p><div class="detector-canvas"><canvas id="ppe-canvas" aria-label="Uploaded image and detection results"></canvas><p id="ppe-placeholder">Your image will appear here.</p></div><div class="sandbox-buttons"><button class="run" id="ppe-run" disabled>Analyze image ↗</button><span id="ppe-status" role="status">Choose an image to begin.</span></div><div id="ppe-result" class="detector-result" aria-live="polite"></div><p class="sandbox-disclaimer">Third-party SafetyVision model: detects workplace PPE including gloves, goggles and masks. Use the detections as a visual demonstration. <a href="https://huggingface.co/ayushgupta7777/safetyvision-yolov8" target="_blank" rel="noopener">Model and AGPL-3.0 license ↗</a></p></div>`;
  document.getElementById('process-view').remove();
  let bitmap=null, previewToken=0;const canvas=document.getElementById('ppe-canvas'),ctx=canvas.getContext('2d'),file=document.getElementById('ppe-file'),button=document.getElementById('ppe-run'),status=document.getElementById('ppe-status'),result=document.getElementById('ppe-result');
  const showStage=mountModelScene(status,['Photo','Prepare','Detect','Annotate']);
  const sample=demo.querySelector('.sample-photo');
  if(location.protocol==='file:'){status.innerHTML='For image inference, open <a href="http://127.0.0.1:4173/#lab-safety">the local portfolio server</a> after starting Start-portfolio.bat.';file.disabled=true;sample.disabled=true;return;}
  async function loadPhoto(item){runToken++;const token=++previewToken;showStage(-1);button.disabled=true;bitmap?.close();bitmap=null;result.textContent='';if(!item)return;if(item.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(item.type)){status.textContent='Choose a JPG, PNG or WebP image under 10 MB.';return}try{showStage(0);status.textContent='Reading the image…';const next=await createImageBitmap(item);if(token!==previewToken||!file.isConnected){next.close();return}bitmap=next;const scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);document.getElementById('ppe-placeholder').hidden=true;button.disabled=false;showStage(0,false,false);status.textContent='Ready to analyze.'}catch(e){status.textContent='Could not open this image. Try another file.'}}
  file.addEventListener('change',()=>loadPhoto(file.files[0]));
  mountPhotoSample(file,sample,status,button,loadPhoto,'construction-workers.jpg');
  button.addEventListener('click',async()=>{if(!bitmap)return;if(location.protocol==='file:'){status.textContent='Start the local portfolio server to run the model; see Start-portfolio.bat.';return}const token=++runToken;showStage(1);button.disabled=true;status.textContent='Loading the model (first run may take a while)…';result.textContent='';try{if(!ppeSessionPromise)ppeSessionPromise=import('./runtime/ort.wasm.min.mjs').then(async ort=>{ort.env.wasm.numThreads=1;ort.env.wasm.wasmPaths=new URL('./runtime/',location.href).href;return {ort,session:await ort.InferenceSession.create('./runtime/ppe-model.onnx',{executionProviders:['wasm']})}}).catch(e=>{ppeSessionPromise=null;throw e});const {ort,session}=await ppeSessionPromise;if(token!==runToken)return;status.textContent='Analyzing the image on your device…';const temp=document.createElement('canvas');temp.width=temp.height=640;const t=temp.getContext('2d',{willReadFrequently:true});t.fillStyle='#727272';t.fillRect(0,0,640,640);const scale=Math.min(640/bitmap.width,640/bitmap.height),w=bitmap.width*scale,h=bitmap.height*scale,dx=(640-w)/2,dy=(640-h)/2;t.drawImage(bitmap,dx,dy,w,h);const pixels=t.getImageData(0,0,640,640).data,plane=640*640,input=new Float32Array(plane*3);for(let i=0;i<plane;i++){input[i]=pixels[i*4]/255;input[plane+i]=pixels[i*4+1]/255;input[2*plane+i]=pixels[i*4+2]/255}showStage(2);const out=(await session.run({images:new ort.Tensor('float32',input,[1,3,640,640])})).output0;if(token!==runToken)return;const classes=['Fall detected','Gloves','Goggles','Hardhat','Mask','No gloves','No goggles','No hardhat','No mask','No safety vest','No harness','Person','Safety vest'];const candidates=[];for(let i=0;i<8400;i++){let cls=0,score=0;for(let c=0;c<13;c++){const v=out.data[(4+c)*8400+i];if(v>score){score=v;cls=c}}if(score<.35)continue;const x=out.data[i],y=out.data[8400+i],bw=out.data[16800+i],bh=out.data[25200+i];candidates.push({cls,score,x1:(x-bw/2-dx)/scale,y1:(y-bh/2-dy)/scale,x2:(x+bw/2-dx)/scale,y2:(y+bh/2-dy)/scale})}candidates.sort((a,b)=>b.score-a.score);const keep=[];function overlap(a,b){const area=(x)=>Math.max(0,x.x2-x.x1)*Math.max(0,x.y2-x.y1);const inter=Math.max(0,Math.min(a.x2,b.x2)-Math.max(a.x1,b.x1))*Math.max(0,Math.min(a.y2,b.y2)-Math.max(a.y1,b.y1));return inter/(area(a)+area(b)-inter||1)}for(const box of candidates){if(keep.length>=50)break;if(!keep.some(k=>k.cls===box.cls&&overlap(k,box)>.45))keep.push(box)}ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const sx=canvas.width/bitmap.width,sy=canvas.height/bitmap.height;ctx.lineWidth=Math.max(2,canvas.width/350);ctx.font=`bold ${Math.max(12,canvas.width/45)}px sans-serif`;for(const b of keep){let x=Math.max(0,b.x1*sx),y=Math.max(0,b.y1*sy),x2=Math.min(canvas.width,b.x2*sx),y2=Math.min(canvas.height,b.y2*sy);if(x2<=x||y2<=y)continue;ctx.strokeStyle='#f28a56';ctx.strokeRect(x,y,x2-x,y2-y);const label=`${classes[b.cls]} ${Math.round(b.score*100)}%`,tw=ctx.measureText(label).width;ctx.fillStyle='#30201b';ctx.fillRect(x,Math.max(0,y-22),tw+10,22);ctx.fillStyle='#fff';ctx.fillText(label,x+5,Math.max(15,y-6))}showStage(3,true);status.textContent='Analysis complete.';result.textContent=keep.length?`${keep.length} detection${keep.length===1?'':'s'} above 35% confidence.`:'No detections above the 35% threshold. Try a different image.';settleReadout(result,true);button.disabled=false}catch(e){console.error(e);if(token!==runToken)return;showStage(-1);status.textContent='The model could not run. Check that the local server is running, then try again.';button.disabled=false}});
}
